update.foreach:
UPDATE ${tableName}
SET readytime = #{timestamps[${index}]}
WHERE id=#{id} AND readytime < #{timestamps[${index}]};

UPDATE car
SET isready = #{isReady}
WHERE id=#{id};

mapper.select:
SELECT id,name,address,latitude,longitude,clas
FROM ${factoryName}
WHERE readytime < CURRENT_TIMESTAMP;

SELECT id,type,`load`,latitude,longitude
FROM car
WHERE isready = 1;
